package com.gameaggregator.gameservice.api;import jakarta.validation.constraints.*;import java.util.UUID;public final class GameDtos{private GameDtos(){}public record Create(@NotNull UUID studioId,UUID publisherId,@NotBlank String slug,@NotBlank String title,String metadata,@NotBlank String visibility,String ageRating){}public record Update(@NotBlank String title,String metadata,@NotBlank String visibility,String ageRating,@NotBlank String status){}public record Classification(@Pattern(regexp="GENRE|CATEGORY|TAG|PLATFORM|LANGUAGE|REGION") String type,@NotBlank String code,@NotBlank String name){}public record Attach(@NotNull UUID taxonomyId){}}